<?php use function App\Core\{csrf, e, url}; $editing = $task !== null; ?>
<div class="form-layout"><a class="back-link" href="<?= url('dashboard') ?>">← Voltar ao painel</a><div class="page-header"><div><span class="eyebrow"><?= $editing ? 'AJUSTE SEUS PLANOS' : 'UM PASSO DE CADA VEZ' ?></span><h1><?= $editing ? 'Editar tarefa' : 'Nova tarefa' ?><span class="accent">.</span></h1><p class="muted">Coloque suas prioridades em ordem.</p></div></div>
<section class="panel form-panel"><div class="form-intro"><span class="form-icon">✎</span><div><h2>Detalhes da tarefa</h2><p class="muted">Preencha as informações abaixo.</p></div></div><form method="post" action="<?= url($editing ? 'tasks/update' : 'tasks/store') ?>" class="form"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><?php if ($editing): ?><input type="hidden" name="id" value="<?= (int)$task['id'] ?>"><?php endif; ?><label>Título da tarefa <span class="required">*</span><input type="text" name="title" maxlength="140" placeholder="Ex.: Estudar PHP e MVC" value="<?= e($task['title'] ?? '') ?>" required></label><label>Descrição <small>(opcional)</small><textarea name="description" maxlength="2000" rows="4" placeholder="Adicione os detalhes que quiser..."><?= e($task['description'] ?? '') ?></textarea></label><div class="form-grid"><label>Prioridade<select name="priority"><option value="baixa" <?= ($task['priority'] ?? '') === 'baixa' ? 'selected' : '' ?>>Baixa</option><option value="media" <?= ($task['priority'] ?? 'media') === 'media' ? 'selected' : '' ?>>Média</option><option value="alta" <?= ($task['priority'] ?? '') === 'alta' ? 'selected' : '' ?>>Alta</option></select></label><label>Data limite <small>(opcional)</small><input type="date" name="due_date" value="<?= e($task['due_date'] ?? '') ?>"></label></div><?php if ($editing): ?><label>Status<select name="status"><option value="pendente" <?= $task['status'] === 'pendente' ? 'selected' : '' ?>>Pendente</option><option value="concluida" <?= $task['status'] === 'concluida' ? 'selected' : '' ?>>Concluída</option></select></label><?php endif; ?><div class="form-actions"><a class="button button-secondary" href="<?= url('dashboard') ?>">Cancelar</a><button class="button button-primary" type="submit"><?= $editing ? 'Salvar alterações' : 'Criar tarefa' ?> →</button></div></form></section></div>
